  fr:{all:'Tous les contenus',known:'3 choses à retenir',refs:'Références bibliographiques',est:'Données établies',komo:'Lecture KŌMØ',limit:'Limites',check:'Faire le KŌMØ Check',share:'Partager',read:'Lecture',library:'KŌMØ Library'},
